create extension if not exists pgcrypto;
create table if not exists public.quizzes (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, title text not null, description text, published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.questions (id uuid primary key default gen_random_uuid(), quiz_id uuid not null references public.quizzes(id) on delete cascade, text text not null, type text not null default 'MULTIPLE_CHOICE', image_url text, explanation text, time_limit integer not null default 20 check(time_limit between 5 and 120), speed_scoring boolean not null default true, position integer not null default 0);
create table if not exists public.answer_options (id uuid primary key default gen_random_uuid(), question_id uuid not null references public.questions(id) on delete cascade, text text not null, is_correct boolean not null default false, position integer not null default 0);
create table if not exists public.game_sessions (id uuid primary key default gen_random_uuid(), quiz_id uuid references public.quizzes(id) on delete set null, pin char(6) not null unique, state text not null default 'LOBBY', host_token_hash text not null, started_at timestamptz, ended_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.players (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.game_sessions(id) on delete cascade, nickname text not null check(char_length(nickname) between 1 and 24), reconnect_token_hash text not null unique, score integer not null default 0, streak integer not null default 0, correct_answers integer not null default 0, total_answers integer not null default 0, total_response_ms integer not null default 0, joined_at timestamptz not null default now(), unique(session_id,nickname));
create table if not exists public.player_answers (id uuid primary key default gen_random_uuid(), player_id uuid not null references public.players(id) on delete cascade, question_id uuid not null references public.questions(id) on delete cascade, correct boolean not null, response_ms integer, points integer not null default 0, submitted_at timestamptz not null default now(), unique(player_id,question_id));
create index if not exists players_session_score_idx on public.players(session_id,score desc);
create index if not exists questions_quiz_position_idx on public.questions(quiz_id,position);
alter table public.quizzes enable row level security; alter table public.questions enable row level security; alter table public.answer_options enable row level security;
create policy "owners manage quizzes" on public.quizzes for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
create policy "owners manage questions" on public.questions for all using(exists(select 1 from public.quizzes q where q.id=quiz_id and q.owner_id=auth.uid())) with check(exists(select 1 from public.quizzes q where q.id=quiz_id and q.owner_id=auth.uid()));
create policy "owners manage options" on public.answer_options for all using(exists(select 1 from public.questions q join public.quizzes z on z.id=q.quiz_id where q.id=question_id and z.owner_id=auth.uid())) with check(exists(select 1 from public.questions q join public.quizzes z on z.id=q.quiz_id where q.id=question_id and z.owner_id=auth.uid()));
